INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$f2495de4$SATQ$, $SATQ$111ca09a-c599-4fa2-82b2-aee6b59db1ea$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Geometry and Trigonometry$SATQ$, $SATQ$S$SATQ$, $SATQ$S.D.$SATQ$, $SATQ$Circles$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">What is the value of&nbsp;<math alttext="cosine StartFraction 565 pi Over 6 EndFraction"><mi>cos</mi><mfrac><mrow><mrow><mn>565</mn></mrow><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>?</p>$SATQ$, $SATQ$[{"id":"eecd33b5-0b8c-448f-b67c-50f10c0e428a","content":"<p style=\"text-align: left;\"><math alttext=\"one half\"><mfrac><mn>1</mn><mn>2</mn></mfrac></math></p>"},{"id":"8f1d1c7d-a032-4d85-b545-bfb79d214095","content":"<p style=\"text-align: left;\"><math alttext=\"1\"><mn>1</mn>\n</math></p>"},{"id":"158a359a-3412-4909-8a36-9d9554bcd814","content":"<p style=\"text-align: left;\"><math alttext=\"StartFraction StartRoot 3 EndRoot Over 2 EndFraction\"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math></p>"},{"id":"fbc86133-b594-489f-9fdc-53a52c733d64","content":"<p style=\"text-align: left;\"><math alttext=\"StartRoot 3 EndRoot\"><msqrt><mn>3</mn></msqrt></math></p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["158a359a-3412-4909-8a36-9d9554bcd814"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice C is correct. The cosine of an angle is equal to the cosine of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="n left parenthesis 2 pi right parenthesis"><mi>n</mi><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo></math> radians more than the angle, where <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="n"><mi>n</mi></math> is an integer constant. Since <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction 565 pi Over 6 EndFraction"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is equivalent to <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction"><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>, <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="cosine left parenthesis StartFraction 565 pi Over 6 EndFraction right parenthesis"><mi>cos</mi><mo>(</mo><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac><mo>)</mo></math> can be rewritten as <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="cosine left parenthesis 47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction right parenthesis"><mi>cos</mi><mo>(</mo><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>, which is equal to <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="cosine left parenthesis StartFraction pi Over 6 EndFraction right parenthesis"><mi>cos</mi><mo>(</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>. Therefore, the value of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="cosine left parenthesis StartFraction 565 pi Over 6 EndFraction right parenthesis"><mi>cos</mi><mo>(</mo><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac><mo>)</mo></math> is equal to the value of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="cosine left parenthesis StartFraction pi Over 6 EndFraction right parenthesis"><mi>cos</mi><mo>(</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>, which is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction StartRoot 3 EndRoot Over 2 EndFraction"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math>.</p>
<p style="text-align: left;">Alternate approach: A trigonometric ratio can be found using the unit circle, that is, a circle with radius&nbsp;<math xmlns="http://www.w3.org/1998/Math/MathML" alttext="1"><mn>1</mn></math> unit. The cosine of a number <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="t"><mi>t</mi></math> is the <em>x</em>-coordinate of the point resulting from traveling a distance of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="t"><mi>t</mi></math> counterclockwise from the point <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 1 comma 0 right parenthesis"><mo>(</mo><mn>1</mn><mo>,</mo><mn>0</mn><mo>)</mo></math> around a unit circle centered at the origin in the <em>xy</em>-plane. A unit circle has a circumference of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="2 pi"><mn>2</mn><mi>&#960;</mi></math>. It follows that since <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction 565 pi Over 6 EndFraction"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is equal to <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction"><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>, traveling a distance of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction 565 pi Over 6 EndFraction"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> counterclockwise around a unit circle means traveling around the circle completely <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="47"><mn>47</mn></math> times and then another <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction pi Over 6 EndFraction"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math> beyond that. That is, traveling <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction 565 pi Over 6 EndFraction"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> results in the same point as traveling <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction pi Over 6 EndFraction"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>. Traveling <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction pi Over 6 EndFraction"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math> counterclockwise from the point <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis 1 comma 0 right parenthesis"><mo>(</mo><mn>1</mn><mo>,</mo><mn>0</mn><mo>)</mo></math> around a unit circle centered at the origin in the <em>xy</em>-plane results in the point <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis StartFraction StartRoot 3 EndRoot Over 2 EndFraction comma one half right parenthesis"><mo>(</mo><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac><mo>,</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>)</mo></math>. Thus, the value of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="cosine StartFraction 565 pi Over 6 EndFraction"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is the <em>x</em>-coordinate of the point <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="left parenthesis StartFraction StartRoot 3 EndRoot Over 2 EndFraction comma one half right parenthesis"><mo>(</mo><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac><mo>,</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>)</mo></math>, which is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction StartRoot 3 EndRoot Over 2 EndFraction"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math>.</p>
<p style="text-align: left;">Choice A is incorrect. This is the value of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="sine StartFraction 565 pi Over 6 EndFraction"><mi>sin</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>, not <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="cosine StartFraction 565 pi Over 6 EndFraction"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>
<p style="text-align: left;">Choice B is incorrect. This is the value of the cosine of a multiple of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="2 pi"><mn>2</mn><mi>&#960;</mi></math>, not&nbsp;<math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartFraction 565 pi Over 6 EndFraction"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>
<p style="text-align: left;">Choice D is incorrect. This is the value of <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="StartStartFraction 1 OverOver tangent StartFraction 565 pi Over 6 EndFraction EndEndFraction"><mfrac><mn>1</mn><mrow><mi>tan</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></mrow></mfrac></math>, not <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="cosine StartFraction 565 pi Over 6 EndFraction"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f2495de4","external_id":"111ca09a-c599-4fa2-82b2-aee6b59db1ea","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"6d602d22-a733-45ad-94ab-d740e6129f3c","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"S","domain":"Geometry and Trigonometry","skill_cd":"S.D.","skill_desc":"Circles","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: left;\">What is the value of&nbsp;<math alttext=\"cosine StartFraction 565 pi Over 6 EndFraction\"><mi>cos</mi><mfrac><mrow><mrow><mn>565</mn></mrow><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>?</p>","answerOptions":[{"id":"eecd33b5-0b8c-448f-b67c-50f10c0e428a","content":"<p style=\"text-align: left;\"><math alttext=\"one half\"><mfrac><mn>1</mn><mn>2</mn></mfrac></math></p>"},{"id":"8f1d1c7d-a032-4d85-b545-bfb79d214095","content":"<p style=\"text-align: left;\"><math alttext=\"1\"><mn>1</mn>\n</math></p>"},{"id":"158a359a-3412-4909-8a36-9d9554bcd814","content":"<p style=\"text-align: left;\"><math alttext=\"StartFraction StartRoot 3 EndRoot Over 2 EndFraction\"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math></p>"},{"id":"fbc86133-b594-489f-9fdc-53a52c733d64","content":"<p style=\"text-align: left;\"><math alttext=\"StartRoot 3 EndRoot\"><msqrt><mn>3</mn></msqrt></math></p>"}],"keys":["158a359a-3412-4909-8a36-9d9554bcd814"],"correct_answer":["C"],"rationale":"<p style=\"text-align: left;\">Choice C is correct. The cosine of an angle is equal to the cosine of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"n left parenthesis 2 pi right parenthesis\"><mi>n</mi><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo></math> radians more than the angle, where <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"n\"><mi>n</mi></math> is an integer constant. Since <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is equivalent to <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction\"><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>, <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis StartFraction 565 pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac><mo>)</mo></math> can be rewritten as <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis 47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>, which is equal to <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis StartFraction pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>. Therefore, the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis StartFraction 565 pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac><mo>)</mo></math> is equal to the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis StartFraction pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>, which is <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction StartRoot 3 EndRoot Over 2 EndFraction\"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math>.</p>\n<p style=\"text-align: left;\">Alternate approach: A trigonometric ratio can be found using the unit circle, that is, a circle with radius&nbsp;<math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"1\"><mn>1</mn></math> unit. The cosine of a number <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"t\"><mi>t</mi></math> is the <em>x</em>-coordinate of the point resulting from traveling a distance of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"t\"><mi>t</mi></math> counterclockwise from the point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 1 comma 0 right parenthesis\"><mo>(</mo><mn>1</mn><mo>,</mo><mn>0</mn><mo>)</mo></math> around a unit circle centered at the origin in the <em>xy</em>-plane. A unit circle has a circumference of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"2 pi\"><mn>2</mn><mi>&#960;</mi></math>. It follows that since <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is equal to <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction\"><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>, traveling a distance of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> counterclockwise around a unit circle means traveling around the circle completely <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"47\"><mn>47</mn></math> times and then another <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction pi Over 6 EndFraction\"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math> beyond that. That is, traveling <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> results in the same point as traveling <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction pi Over 6 EndFraction\"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>. Traveling <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction pi Over 6 EndFraction\"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math> counterclockwise from the point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 1 comma 0 right parenthesis\"><mo>(</mo><mn>1</mn><mo>,</mo><mn>0</mn><mo>)</mo></math> around a unit circle centered at the origin in the <em>xy</em>-plane results in the point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis StartFraction StartRoot 3 EndRoot Over 2 EndFraction comma one half right parenthesis\"><mo>(</mo><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac><mo>,</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>)</mo></math>. Thus, the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine StartFraction 565 pi Over 6 EndFraction\"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is the <em>x</em>-coordinate of the point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis StartFraction StartRoot 3 EndRoot Over 2 EndFraction comma one half right parenthesis\"><mo>(</mo><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac><mo>,</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>)</mo></math>, which is <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction StartRoot 3 EndRoot Over 2 EndFraction\"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect. This is the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"sine StartFraction 565 pi Over 6 EndFraction\"><mi>sin</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>, not <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine StartFraction 565 pi Over 6 EndFraction\"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>\n<p style=\"text-align: left;\">Choice B is incorrect. This is the value of the cosine of a multiple of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"2 pi\"><mn>2</mn><mi>&#960;</mi></math>, not&nbsp;<math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>\n<p style=\"text-align: left;\">Choice D is incorrect. This is the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartStartFraction 1 OverOver tangent StartFraction 565 pi Over 6 EndFraction EndEndFraction\"><mfrac><mn>1</mn><mrow><mi>tan</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></mrow></mfrac></math>, not <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine StartFraction 565 pi Over 6 EndFraction\"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"image_count":0,"raw_list":{"updateDate":1755117017716,"pPcc":"SAT#S","questionId":"f2495de4","skill_cd":"S.D.","score_band_range_cd":3,"skill_desc":"Circles","createDate":1755117017716,"program":"SAT","primary_class_cd_desc":"Geometry and Trigonometry","ibn":"","external_id":"111ca09a-c599-4fa2-82b2-aee6b59db1ea","primary_class_cd":"S","uId":"6d602d22-a733-45ad-94ab-d740e6129f3c","difficulty":"E"},"raw_detail":{"type":"mcq","stem":"<p style=\"text-align: left;\">What is the value of&nbsp;<math alttext=\"cosine StartFraction 565 pi Over 6 EndFraction\"><mi>cos</mi><mfrac><mrow><mrow><mn>565</mn></mrow><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>?</p>","keys":["158a359a-3412-4909-8a36-9d9554bcd814"],"answerOptions":[{"id":"eecd33b5-0b8c-448f-b67c-50f10c0e428a","content":"<p style=\"text-align: left;\"><math alttext=\"one half\"><mfrac><mn>1</mn><mn>2</mn></mfrac></math></p>"},{"id":"8f1d1c7d-a032-4d85-b545-bfb79d214095","content":"<p style=\"text-align: left;\"><math alttext=\"1\"><mn>1</mn>\n</math></p>"},{"id":"158a359a-3412-4909-8a36-9d9554bcd814","content":"<p style=\"text-align: left;\"><math alttext=\"StartFraction StartRoot 3 EndRoot Over 2 EndFraction\"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math></p>"},{"id":"fbc86133-b594-489f-9fdc-53a52c733d64","content":"<p style=\"text-align: left;\"><math alttext=\"StartRoot 3 EndRoot\"><msqrt><mn>3</mn></msqrt></math></p>"}],"rationale":"<p style=\"text-align: left;\">Choice C is correct. The cosine of an angle is equal to the cosine of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"n left parenthesis 2 pi right parenthesis\"><mi>n</mi><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo></math> radians more than the angle, where <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"n\"><mi>n</mi></math> is an integer constant. Since <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is equivalent to <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction\"><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>, <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis StartFraction 565 pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac><mo>)</mo></math> can be rewritten as <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis 47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>, which is equal to <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis StartFraction pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>. Therefore, the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis StartFraction 565 pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac><mo>)</mo></math> is equal to the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine left parenthesis StartFraction pi Over 6 EndFraction right parenthesis\"><mi>cos</mi><mo>(</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac><mo>)</mo></math>, which is <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction StartRoot 3 EndRoot Over 2 EndFraction\"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math>.</p>\n<p style=\"text-align: left;\">Alternate approach: A trigonometric ratio can be found using the unit circle, that is, a circle with radius&nbsp;<math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"1\"><mn>1</mn></math> unit. The cosine of a number <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"t\"><mi>t</mi></math> is the <em>x</em>-coordinate of the point resulting from traveling a distance of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"t\"><mi>t</mi></math> counterclockwise from the point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 1 comma 0 right parenthesis\"><mo>(</mo><mn>1</mn><mo>,</mo><mn>0</mn><mo>)</mo></math> around a unit circle centered at the origin in the <em>xy</em>-plane. A unit circle has a circumference of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"2 pi\"><mn>2</mn><mi>&#960;</mi></math>. It follows that since <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is equal to <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"47 left parenthesis 2 pi right parenthesis plus StartFraction pi Over 6 EndFraction\"><mn>47</mn><mo>(</mo><mn>2</mn><mi>&#960;</mi><mo>)</mo><mo>+</mo><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>, traveling a distance of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> counterclockwise around a unit circle means traveling around the circle completely <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"47\"><mn>47</mn></math> times and then another <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction pi Over 6 EndFraction\"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math> beyond that. That is, traveling <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> results in the same point as traveling <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction pi Over 6 EndFraction\"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math>. Traveling <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction pi Over 6 EndFraction\"><mfrac><mi>&#960;</mi><mn>6</mn></mfrac></math> counterclockwise from the point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis 1 comma 0 right parenthesis\"><mo>(</mo><mn>1</mn><mo>,</mo><mn>0</mn><mo>)</mo></math> around a unit circle centered at the origin in the <em>xy</em>-plane results in the point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis StartFraction StartRoot 3 EndRoot Over 2 EndFraction comma one half right parenthesis\"><mo>(</mo><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac><mo>,</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>)</mo></math>. Thus, the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine StartFraction 565 pi Over 6 EndFraction\"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math> is the <em>x</em>-coordinate of the point <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"left parenthesis StartFraction StartRoot 3 EndRoot Over 2 EndFraction comma one half right parenthesis\"><mo>(</mo><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac><mo>,</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>)</mo></math>, which is <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction StartRoot 3 EndRoot Over 2 EndFraction\"><mfrac><msqrt><mn>3</mn></msqrt><mn>2</mn></mfrac></math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect. This is the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"sine StartFraction 565 pi Over 6 EndFraction\"><mi>sin</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>, not <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine StartFraction 565 pi Over 6 EndFraction\"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>\n<p style=\"text-align: left;\">Choice B is incorrect. This is the value of the cosine of a multiple of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"2 pi\"><mn>2</mn><mi>&#960;</mi></math>, not&nbsp;<math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartFraction 565 pi Over 6 EndFraction\"><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>\n<p style=\"text-align: left;\">Choice D is incorrect. This is the value of <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"StartStartFraction 1 OverOver tangent StartFraction 565 pi Over 6 EndFraction EndEndFraction\"><mfrac><mn>1</mn><mrow><mi>tan</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></mrow></mfrac></math>, not <math xmlns=\"http://www.w3.org/1998/Math/MathML\" alttext=\"cosine StartFraction 565 pi Over 6 EndFraction\"><mi>cos</mi><mfrac><mrow><mn>565</mn><mi>&#960;</mi></mrow><mn>6</mn></mfrac></math>.</p>","externalid":"111ca09a-c599-4fa2-82b2-aee6b59db1ea","correct_answer":["C"]},"createDate":1755117017716,"updateDate":1755117017716}$SATQ$::jsonb, 1755117017716, 1755117017716),
    ($SATQ$f329442c$SATQ$, $SATQ$64a7c0bf-065d-47a5-a938-4a1fabad6933$SATQ$::uuid, $SATQ$4223b6b8-f999-45e7-9097-2b77f57f3208$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Geometry and Trigonometry$SATQ$, $SATQ$S$SATQ$, $SATQ$S.A.$SATQ$, $SATQ$Area and volume$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">Circle <math alttext="upper A"><mi>A</mi>
</math><em>&nbsp;</em>has a radius of <math alttext="3 n"><mrow>
	<mn>3</mn>
	<mi>n</mi>
</mrow>
</math> and circle <math alttext="upper B"><mi>B</mi>
</math><em>&nbsp;</em>has a radius of <math alttext="129 n"><mrow>
	<mn>129</mn>
	<mi>n</mi>
</mrow>
</math>, where <math alttext="n"><mi>n</mi>
</math> is a positive constant. The area of circle <math alttext="upper B"><mi>B</mi>
</math><em>&nbsp;</em>is how many times the area of circle <math alttext="upper A"><mi>A</mi>
</math>?</p>$SATQ$, $SATQ$[{"id":"de97b7db-e754-49a1-a73d-27d18dffc8c5","content":"<p><math alttext=\"43\"><mn>43</mn>\n</math></p>"},{"id":"0bd3e3b0-71d8-48b6-96f2-15bf1ac29991","content":"<p><math alttext=\"86\"><mn>86</mn>\n</math></p>"},{"id":"632d807a-921e-4b60-97f0-5d493d7fc238","content":"<p><math alttext=\"129\"><mn>129</mn>\n</math></p>"},{"id":"9a58900b-f648-4154-81de-bee847a8bb9f","content":"<p><math alttext=\"1,849\"><mn>1,849</mn>\n</math></p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["9a58900b-f648-4154-81de-bee847a8bb9f"]$SATQ$::jsonb, $SATQ$<p>Choice D is correct. The area of a circle can be found by using the formula <math alttext="upper A equals pi r squared"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math>, where <math alttext="upper A"><mi>A</mi>
</math> is the area and <math alttext="r"><mi>r</mi>
</math> is the radius of the circle. It&rsquo;s given that the radius of circle <em>A</em> is <math alttext="3 n"><mn>3</mn><mi>n</mi></math>. Substituting this value for <math alttext="r"><mi>r</mi>
</math> into the formula&nbsp;<math alttext="upper A equals pi r squared"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math> gives <math alttext="upper A equals pi left parenthesis 3 n right parenthesis squared"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mfenced><mrow><mn>3</mn><mi>n</mi></mrow></mfenced><mn>2</mn></msup></math>, or <math alttext="9 pi n squared"><mn>9</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></math>. It&rsquo;s also given that the radius of circle <em>B</em> is <math alttext="129 n"><mn>129</mn><mi>n</mi></math>. Substituting this value for <math alttext="r"><mi>r</mi>
</math> into the formula <math alttext="upper A equals pi r squared"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math> gives <math alttext="upper A equals pi left parenthesis 129 n right parenthesis squared"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mfenced><mrow><mn>129</mn><mi>n</mi></mrow></mfenced><mn>2</mn></msup></math>, or <math alttext="16,641 pi n squared"><mn>16,641</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></math>. Dividing the area of circle <em>B</em> by the area of circle <em>A</em> gives <math alttext="StartFraction 16,641 pi n squared Over 9 pi n squared EndFraction"><mfrac><mrow><mn>16,641</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></mrow><mrow><mn>9</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></mrow></mfrac></math>, which simplifies to <math alttext="1,849"><mn>1,849</mn>
</math>. Therefore, the area of circle <em>B</em> is <math alttext="1,849"><mn>1,849</mn>
</math> times the area of circle <em>A</em>.</p>
<p>Choice A is incorrect. This is how many times greater the radius of circle <em>B</em> is than the radius of circle <em>A</em>.</p>
<p>Choice B is incorrect and may result from conceptual or calculation errors.</p>
<p>Choice C is incorrect. This is the coefficient on the term that describes the radius of circle <em>B</em>.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, $SATQ$manifold$SATQ$, NULL, NULL, NULL, $SATQ${"questionId":"f329442c","external_id":"64a7c0bf-065d-47a5-a938-4a1fabad6933","disclosed_item_id":null,"source":"qbank","vaultid":"4223b6b8-f999-45e7-9097-2b77f57f3208","uId":"c6ca457a-497f-45a8-847f-fd110769f249","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"S","domain":"Geometry and Trigonometry","skill_cd":"S.A.","skill_desc":"Area and volume","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: left;\">Circle <math alttext=\"upper A\"><mi>A</mi>\n</math><em>&nbsp;</em>has a radius of <math alttext=\"3 n\"><mrow>\n\t<mn>3</mn>\n\t<mi>n</mi>\n</mrow>\n</math> and circle <math alttext=\"upper B\"><mi>B</mi>\n</math><em>&nbsp;</em>has a radius of <math alttext=\"129 n\"><mrow>\n\t<mn>129</mn>\n\t<mi>n</mi>\n</mrow>\n</math>, where <math alttext=\"n\"><mi>n</mi>\n</math> is a positive constant. The area of circle <math alttext=\"upper B\"><mi>B</mi>\n</math><em>&nbsp;</em>is how many times the area of circle <math alttext=\"upper A\"><mi>A</mi>\n</math>?</p>","answerOptions":[{"id":"de97b7db-e754-49a1-a73d-27d18dffc8c5","content":"<p><math alttext=\"43\"><mn>43</mn>\n</math></p>"},{"id":"0bd3e3b0-71d8-48b6-96f2-15bf1ac29991","content":"<p><math alttext=\"86\"><mn>86</mn>\n</math></p>"},{"id":"632d807a-921e-4b60-97f0-5d493d7fc238","content":"<p><math alttext=\"129\"><mn>129</mn>\n</math></p>"},{"id":"9a58900b-f648-4154-81de-bee847a8bb9f","content":"<p><math alttext=\"1,849\"><mn>1,849</mn>\n</math></p>"}],"keys":["9a58900b-f648-4154-81de-bee847a8bb9f"],"correct_answer":["D"],"rationale":"<p>Choice D is correct. The area of a circle can be found by using the formula <math alttext=\"upper A equals pi r squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math>, where <math alttext=\"upper A\"><mi>A</mi>\n</math> is the area and <math alttext=\"r\"><mi>r</mi>\n</math> is the radius of the circle. It&rsquo;s given that the radius of circle <em>A</em> is <math alttext=\"3 n\"><mn>3</mn><mi>n</mi></math>. Substituting this value for <math alttext=\"r\"><mi>r</mi>\n</math> into the formula&nbsp;<math alttext=\"upper A equals pi r squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math> gives <math alttext=\"upper A equals pi left parenthesis 3 n right parenthesis squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mfenced><mrow><mn>3</mn><mi>n</mi></mrow></mfenced><mn>2</mn></msup></math>, or <math alttext=\"9 pi n squared\"><mn>9</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></math>. It&rsquo;s also given that the radius of circle <em>B</em> is <math alttext=\"129 n\"><mn>129</mn><mi>n</mi></math>. Substituting this value for <math alttext=\"r\"><mi>r</mi>\n</math> into the formula <math alttext=\"upper A equals pi r squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math> gives <math alttext=\"upper A equals pi left parenthesis 129 n right parenthesis squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mfenced><mrow><mn>129</mn><mi>n</mi></mrow></mfenced><mn>2</mn></msup></math>, or <math alttext=\"16,641 pi n squared\"><mn>16,641</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></math>. Dividing the area of circle <em>B</em> by the area of circle <em>A</em> gives <math alttext=\"StartFraction 16,641 pi n squared Over 9 pi n squared EndFraction\"><mfrac><mrow><mn>16,641</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></mrow><mrow><mn>9</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></mrow></mfrac></math>, which simplifies to <math alttext=\"1,849\"><mn>1,849</mn>\n</math>. Therefore, the area of circle <em>B</em> is <math alttext=\"1,849\"><mn>1,849</mn>\n</math> times the area of circle <em>A</em>.</p>\n<p>Choice A is incorrect. This is how many times greater the radius of circle <em>B</em> is than the radius of circle <em>A</em>.</p>\n<p>Choice B is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice C is incorrect. This is the coefficient on the term that describes the radius of circle <em>B</em>.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":"manifold","position":null,"image_count":0,"raw_list":{"updateDate":1691007959837,"pPcc":"SAT#S","questionId":"f329442c","skill_cd":"S.A.","score_band_range_cd":6,"skill_desc":"Area and volume","createDate":1691007959837,"program":"SAT","primary_class_cd_desc":"Geometry and Trigonometry","ibn":null,"external_id":"64a7c0bf-065d-47a5-a938-4a1fabad6933","primary_class_cd":"S","uId":"c6ca457a-497f-45a8-847f-fd110769f249","difficulty":"H"},"raw_detail":{"keys":["9a58900b-f648-4154-81de-bee847a8bb9f"],"rationale":"<p>Choice D is correct. The area of a circle can be found by using the formula <math alttext=\"upper A equals pi r squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math>, where <math alttext=\"upper A\"><mi>A</mi>\n</math> is the area and <math alttext=\"r\"><mi>r</mi>\n</math> is the radius of the circle. It&rsquo;s given that the radius of circle <em>A</em> is <math alttext=\"3 n\"><mn>3</mn><mi>n</mi></math>. Substituting this value for <math alttext=\"r\"><mi>r</mi>\n</math> into the formula&nbsp;<math alttext=\"upper A equals pi r squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math> gives <math alttext=\"upper A equals pi left parenthesis 3 n right parenthesis squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mfenced><mrow><mn>3</mn><mi>n</mi></mrow></mfenced><mn>2</mn></msup></math>, or <math alttext=\"9 pi n squared\"><mn>9</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></math>. It&rsquo;s also given that the radius of circle <em>B</em> is <math alttext=\"129 n\"><mn>129</mn><mi>n</mi></math>. Substituting this value for <math alttext=\"r\"><mi>r</mi>\n</math> into the formula <math alttext=\"upper A equals pi r squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mi>r</mi><mn>2</mn></msup></math> gives <math alttext=\"upper A equals pi left parenthesis 129 n right parenthesis squared\"><mi>A</mi><mo>=</mo><mi>π</mi><msup><mfenced><mrow><mn>129</mn><mi>n</mi></mrow></mfenced><mn>2</mn></msup></math>, or <math alttext=\"16,641 pi n squared\"><mn>16,641</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></math>. Dividing the area of circle <em>B</em> by the area of circle <em>A</em> gives <math alttext=\"StartFraction 16,641 pi n squared Over 9 pi n squared EndFraction\"><mfrac><mrow><mn>16,641</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></mrow><mrow><mn>9</mn><mi>π</mi><msup><mi>n</mi><mn>2</mn></msup></mrow></mfrac></math>, which simplifies to <math alttext=\"1,849\"><mn>1,849</mn>\n</math>. Therefore, the area of circle <em>B</em> is <math alttext=\"1,849\"><mn>1,849</mn>\n</math> times the area of circle <em>A</em>.</p>\n<p>Choice A is incorrect. This is how many times greater the radius of circle <em>B</em> is than the radius of circle <em>A</em>.</p>\n<p>Choice B is incorrect and may result from conceptual or calculation errors.</p>\n<p>Choice C is incorrect. This is the coefficient on the term that describes the radius of circle <em>B</em>.</p>","origin":"manifold","stem":"<p style=\"text-align: left;\">Circle <math alttext=\"upper A\"><mi>A</mi>\n</math><em>&nbsp;</em>has a radius of <math alttext=\"3 n\"><mrow>\n\t<mn>3</mn>\n\t<mi>n</mi>\n</mrow>\n</math> and circle <math alttext=\"upper B\"><mi>B</mi>\n</math><em>&nbsp;</em>has a radius of <math alttext=\"129 n\"><mrow>\n\t<mn>129</mn>\n\t<mi>n</mi>\n</mrow>\n</math>, where <math alttext=\"n\"><mi>n</mi>\n</math> is a positive constant. The area of circle <math alttext=\"upper B\"><mi>B</mi>\n</math><em>&nbsp;</em>is how many times the area of circle <math alttext=\"upper A\"><mi>A</mi>\n</math>?</p>","externalid":"64a7c0bf-065d-47a5-a938-4a1fabad6933","templateid":"60431629-bbf0-45cb-b33c-e9b065bb94a4","vaultid":"4223b6b8-f999-45e7-9097-2b77f57f3208","type":"mcq","answerOptions":[{"id":"de97b7db-e754-49a1-a73d-27d18dffc8c5","content":"<p><math alttext=\"43\"><mn>43</mn>\n</math></p>"},{"id":"0bd3e3b0-71d8-48b6-96f2-15bf1ac29991","content":"<p><math alttext=\"86\"><mn>86</mn>\n</math></p>"},{"id":"632d807a-921e-4b60-97f0-5d493d7fc238","content":"<p><math alttext=\"129\"><mn>129</mn>\n</math></p>"},{"id":"9a58900b-f648-4154-81de-bee847a8bb9f","content":"<p><math alttext=\"1,849\"><mn>1,849</mn>\n</math></p>"}],"correct_answer":["D"]},"createDate":1691007959837,"updateDate":1691007959837}$SATQ$::jsonb, 1691007959837, 1691007959837),
    ($SATQ$f39f88b7$SATQ$, $SATQ$7b4cffc9-9565-413b-810d-67d7f92aa56e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Geometry and Trigonometry$SATQ$, $SATQ$S$SATQ$, $SATQ$S.A.$SATQ$, $SATQ$Area and volume$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$spr$SATQ$, NULL, $SATQ$<p style="text-align: left;">A triangle has a base length of <math alttext="40"><mn>40</mn>
</math> centimeters and a height of <math alttext="90"><mn>90</mn>
</math> centimeters. What is the area, in square centimeters, of the triangle?</p>$SATQ$, $SATQ$[]$SATQ$::jsonb, $SATQ$["1800"]$SATQ$::jsonb, $SATQ$["1800"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">The correct answer is <math alttext="1,800"><mn>1,800</mn>
</math>. The area, <math alttext="upper A"><mi>A</mi>
</math>, of a triangle can be found using the formula <math alttext="upper A equals one half b h"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>b</mi><mi>h</mi></math>, where <math alttext="b"><mi>b</mi>
</math> is the base length of the triangle and <math alttext="h"><mi>h</mi>
</math> is the height of the triangle. It&rsquo;s given that the triangle has a base length of <math alttext="40"><mn>40</mn>
</math> centimeters and a height of <math alttext="90"><mn>90</mn>
</math> centimeters. Substituting <math alttext="40"><mn>40</mn>
</math> for <math alttext="b"><mi>b</mi>
</math> and <math alttext="90"><mn>90</mn>
</math> for <math alttext="h"><mi>h</mi>
</math> in the formula <math alttext="upper A equals one half b h"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>b</mi><mi>h</mi></math> yields <math alttext="upper A equals one half left parenthesis 40 right parenthesis left parenthesis 90 right parenthesis"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mfenced><mn>40</mn></mfenced><mfenced><mn>90</mn></mfenced></math>, or <math alttext="upper A equals 1,800"><mrow>
	<mi>A</mi>
	<mo>=</mo>
	<mn>1,800</mn>
</mrow>
</math>. Therefore, the area, in square centimeters, of the triangle is <math alttext="1,800"><mn>1,800</mn>
</math>.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f39f88b7","external_id":"7b4cffc9-9565-413b-810d-67d7f92aa56e","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"c767f21d-3f84-4ab2-bf35-e022e7c09ba3","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"S","domain":"Geometry and Trigonometry","skill_cd":"S.A.","skill_desc":"Area and volume","difficulty":"E","score_band_range_cd":3,"type":"spr","stimulus":null,"stem":"<p style=\"text-align: left;\">A triangle has a base length of <math alttext=\"40\"><mn>40</mn>\n</math> centimeters and a height of <math alttext=\"90\"><mn>90</mn>\n</math> centimeters. What is the area, in square centimeters, of the triangle?</p>","answerOptions":[],"keys":["1800"],"correct_answer":["1800"],"rationale":"<p style=\"text-align: left;\">The correct answer is <math alttext=\"1,800\"><mn>1,800</mn>\n</math>. The area, <math alttext=\"upper A\"><mi>A</mi>\n</math>, of a triangle can be found using the formula <math alttext=\"upper A equals one half b h\"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>b</mi><mi>h</mi></math>, where <math alttext=\"b\"><mi>b</mi>\n</math> is the base length of the triangle and <math alttext=\"h\"><mi>h</mi>\n</math> is the height of the triangle. It&rsquo;s given that the triangle has a base length of <math alttext=\"40\"><mn>40</mn>\n</math> centimeters and a height of <math alttext=\"90\"><mn>90</mn>\n</math> centimeters. Substituting <math alttext=\"40\"><mn>40</mn>\n</math> for <math alttext=\"b\"><mi>b</mi>\n</math> and <math alttext=\"90\"><mn>90</mn>\n</math> for <math alttext=\"h\"><mi>h</mi>\n</math> in the formula <math alttext=\"upper A equals one half b h\"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mi>b</mi><mi>h</mi></math> yields <math alttext=\"upper A equals one half left parenthesis 40 right parenthesis left parenthesis 90 right parenthesis\"><mi>A</mi><mo>=</mo><mfrac><mn>1</mn><mn>